package dev.arena.dota2port;

import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Paint;
import android.graphics.RectF;
import android.util.SparseArray;
import android.view.MotionEvent;
import android.view.View;

import org.json.JSONArray;
import org.json.JSONObject;

import java.util.ArrayList;
import java.util.List;

/**
 * Dota 2 touch overlay. Reads assets/dota2/controls.json (generated by
 * tools/gen_touch_profile.py), draws 28 controls and emits events to InputBridge.
 *
 * Right-click movement: the big MOVE button has mouseMoveMode=true — dragging moves
 * the cursor, tapping sends MOUSE_RIGHT_BUTTON. The runtime (Wine/XTest bridge, M4)
 * decides how to turn that into a Dota 2 order; this view only emits intents.
 */
public class TouchOverlayView extends View {
    private static final String TAG = "Dota2Overlay";

    private static final class Ctrl {
        String id, label, type, shape, binding;
        float x, y, scale;
        boolean mouseMoveMode, toggle;
        float cx, cy, radius;
        RectF box;
        boolean pressed;
    }

    private final List<Ctrl> controls = new ArrayList<>();
    private final SparseArray<Ctrl> active = new SparseArray<>();
    private final SparseArray<Float> lastX = new SparseArray<>();
    private final SparseArray<Float> lastY = new SparseArray<>();
    private final Paint fill = new Paint(Paint.ANTI_ALIAS_FLAG);
    private final Paint stroke = new Paint(Paint.ANTI_ALIAS_FLAG);
    private final Paint text = new Paint(Paint.ANTI_ALIAS_FLAG);
    private boolean enabled = true;
    private int width, height;

    public TouchOverlayView(Context ctx, String profileJson) {
        super(ctx);
        initPaint();
        try {
            JSONObject root = new JSONObject(profileJson);
            JSONArray arr = root.getJSONArray("controls");
            for (int i = 0; i < arr.length(); i++) {
                JSONObject o = arr.getJSONObject(i);
                Ctrl c = new Ctrl();
                c.id = o.optString("id", "ctrl" + i);
                c.label = o.optString("label", c.id);
                c.type = o.optString("type", "button");
                c.shape = o.optString("shape", "CIRCLE");
                c.binding = o.optString("binding", "NONE");
                c.x = (float) o.optDouble("x", 0.5);
                c.y = (float) o.optDouble("y", 0.5);
                c.scale = (float) o.optDouble("scale", 1.0);
                c.mouseMoveMode = o.optBoolean("mouseMoveMode", false);
                c.toggle = o.optBoolean("toggle", false);
                controls.add(c);
            }
        } catch (Exception e) {
            android.util.Log.e(TAG, "cannot parse controls.json: " + e);
        }
        setWillNotDraw(false);
    }

    private void initPaint() {
        fill.setStyle(Paint.Style.FILL);
        stroke.setStyle(Paint.Style.STROKE);
        stroke.setStrokeWidth(3f);
        text.setColor(Color.WHITE);
        text.setTextAlign(Paint.Align.CENTER);
        text.setTextSize(20f);
        text.setFakeBoldText(true);
    }

    public void setControlsEnabled(boolean value) {
        enabled = value;
        setAlpha(value ? 1.0f : 0.35f);
        invalidate();
    }

    public int getControlCount() { return controls.size(); }

    @Override
    protected void onSizeChanged(int w, int h, int oldw, int oldh) {
        width = w;
        height = h;
        float unit = Math.min(w, h) * 0.045f;
        for (Ctrl c : controls) {
            c.cx = c.x * w;
            c.cy = c.y * h;
            c.radius = unit * c.scale;
            if ("trackpad".equals(c.type)) {
                float hw = w * 0.13f * c.scale;
                float hh = h * 0.20f * c.scale;
                c.box = new RectF(c.cx - hw, c.cy - hh, c.cx + hw, c.cy + hh);
            } else {
                c.box = null;
            }
        }
        text.setTextSize(Math.max(12f, unit * 0.42f));
    }

    @Override
    protected void onDraw(Canvas canvas) {
        super.onDraw(canvas);
        for (Ctrl c : controls) {
            boolean track = "trackpad".equals(c.type);
            fill.setColor(track ? 0x442F6FD0 : (c.pressed ? 0xAAE0A040 : 0x66C23B22));
            stroke.setColor(c.pressed ? Color.WHITE : 0xCCF0C674);
            if (c.box != null) {
                canvas.drawRoundRect(c.box, 18f, 18f, fill);
                canvas.drawRoundRect(c.box, 18f, 18f, stroke);
            } else {
                canvas.drawCircle(c.cx, c.cy, c.radius, fill);
                canvas.drawCircle(c.cx, c.cy, c.radius, stroke);
            }
            canvas.drawText(c.label, c.cx, c.cy + text.getTextSize() * 0.35f, text);
        }
    }

    private Ctrl hit(float x, float y) {
        for (int i = controls.size() - 1; i >= 0; i--) {
            Ctrl c = controls.get(i);
            if (c.box != null) {
                if (c.box.contains(x, y)) return c;
            } else {
                float dx = x - c.cx, dy = y - c.cy;
                if (dx * dx + dy * dy <= c.radius * c.radius * 1.5f) return c;
            }
        }
        return null;
    }

    private String event(String type, Ctrl c, float dx, float dy) {
        StringBuilder sb = new StringBuilder();
        sb.append("{\"t\":\"").append(type).append('"')
          .append(",\"id\":\"").append(esc(c.id)).append('"')
          .append(",\"binding\":\"").append(esc(c.binding)).append('"')
          .append(",\"type\":\"").append(esc(c.type)).append('"');
        if (type.equals("move")) {
            sb.append(",\"dx\":").append(String.format(java.util.Locale.US, "%.2f", dx))
              .append(",\"dy\":").append(String.format(java.util.Locale.US, "%.2f", dy));
        }
        sb.append(",\"mouseMoveMode\":").append(c.mouseMoveMode)
          .append(",\"toggle\":").append(c.toggle).append('}');
        return sb.toString();
    }

    private static String esc(String s) {
        return s == null ? "" : s.replace("\\", "\\\\").replace("\"", "\\\"");
    }

    @Override
    public boolean onTouchEvent(MotionEvent ev) {
        if (!enabled) return false; // let the buttons underneath receive the touch
        int action = ev.getActionMasked();
        int index = ev.getActionIndex();
        int pid = ev.getPointerId(index);
        float x = ev.getX(index), y = ev.getY(index);

        switch (action) {
            case MotionEvent.ACTION_DOWN:
            case MotionEvent.ACTION_POINTER_DOWN: {
                Ctrl c = hit(x, y);
                if (c == null) return false;
                active.put(pid, c);
                lastX.put(pid, x);
                lastY.put(pid, y);
                c.pressed = true;
                InputBridge.get().send(event("down", c, 0, 0));
                invalidate();
                return true;
            }
            case MotionEvent.ACTION_MOVE: {
                boolean handled = false;
                for (int i = 0; i < ev.getPointerCount(); i++) {
                    int id = ev.getPointerId(i);
                    Ctrl c = active.get(id);
                    if (c == null) continue;
                    float px = lastX.get(id, ev.getX(i));
                    float py = lastY.get(id, ev.getY(i));
                    float dx = ev.getX(i) - px, dy = ev.getY(i) - py;
                    if (c.mouseMoveMode || "trackpad".equals(c.type) || "stick".equals(c.type)) {
                        InputBridge.get().send(event("move", c, dx, dy));
                    }
                    lastX.put(id, ev.getX(i));
                    lastY.put(id, ev.getY(i));
                    handled = true;
                }
                return handled;
            }
            case MotionEvent.ACTION_UP:
            case MotionEvent.ACTION_POINTER_UP:
            case MotionEvent.ACTION_CANCEL: {
                Ctrl c = active.get(pid);
                if (c == null) return false;
                active.remove(pid);
                lastX.remove(pid);
                lastY.remove(pid);
                c.pressed = false;
                InputBridge.get().send(event("up", c, 0, 0));
                invalidate();
                return true;
            }
            default:
                return super.onTouchEvent(ev);
        }
    }
}
